class Trie:
    def __init__(self):
        self.root = {}

    def insert(self, word):
        n = self.root
        for c in word:
            n = n.setdefault(c, {})
        n['$'] = True

    def _walk(self, s):
        n = self.root
        for c in s:
            if c not in n:
                return None
            n = n[c]
        return n

    def search(self, word):
        n = self._walk(word)
        return n is not None and '$' in n

    def starts_with(self, prefix):
        return self._walk(prefix) is not None
